def run(data):
    """Create a fresh, roster-ordered allocation using runtime room capacities.

    Existing assignments and reservations are intentionally ignored. Invalid
    input raises ValueError; unknown preference IDs simply provide no seat.
    """
    if not isinstance(data, dict):
        raise ValueError('Input must be an object.')

    schemas = {
        'participants': {'id': str, 'name': str, 'email': str,
                         'first_choice': str, 'second_choice': str},
        'rooms': {'id': str, 'name': str, 'capacity': int, 'open': bool},
        'workshops': {'id': str, 'name': str, 'room': str, 'time': str},
    }
    indexed = {}
    for collection, fields in schemas.items():
        if collection not in data or not isinstance(data[collection], list):
            raise ValueError(f'{collection} must be an array.')
        by_id = {}
        for position, record in enumerate(data[collection]):
            label = f'{collection}[{position}]'
            if not isinstance(record, dict):
                raise ValueError(f'{label} must be an object.')
            for field, expected_type in fields.items():
                if field not in record:
                    raise ValueError(f'{label} is missing required field {field}.')
                value = record[field]
                if expected_type is int:
                    valid = isinstance(value, int) and not isinstance(value, bool)
                else:
                    valid = isinstance(value, expected_type)
                if not valid:
                    type_name = {str: 'string', int: 'integer', bool: 'boolean'}[expected_type]
                    raise ValueError(f'{label}.{field} must be a {type_name}.')
            identifier = record['id']
            if identifier in by_id:
                raise ValueError(f'Duplicate ID in {collection}: {identifier!r}.')
            if collection == 'rooms' and record['capacity'] < 0:
                raise ValueError(f'Room {identifier!r} has a negative capacity.')
            by_id[identifier] = record
        indexed[collection] = by_id

    rooms = indexed['rooms']
    workshops = indexed['workshops']
    for workshop in data['workshops']:
        if workshop['room'] not in rooms:
            raise ValueError(
                f'Workshop {workshop["id"]!r} references missing room {workshop["room"]!r}.'
            )

    remaining = {
        room_id: room['capacity'] if room['open'] else 0
        for room_id, room in rooms.items()
    }
    assignments = []
    waitlist = []
    for participant in data['participants']:
        for choice in (participant['first_choice'], participant['second_choice']):
            workshop = workshops.get(choice)
            if workshop is None:
                continue
            room_id = workshop['room']
            if remaining[room_id] > 0:
                assignments.append({
                    'participant_id': participant['id'],
                    'workshop_id': workshop['id'],
                })
                remaining[room_id] -= 1
                break
        else:
            waitlist.append(participant['id'])

    return {'assignments': assignments, 'waitlist': waitlist}

def run(data):
    """Replan allocations using runtime capacities and existing reservations."""
    if not isinstance(data, dict):
        raise ValueError('Input must be an object.')

    def array(key):
        if key not in data or not isinstance(data[key], list):
            raise ValueError(f'{key} must be an array.')
        return data[key]

    def string_field(record, key, context):
        if not isinstance(record, dict):
            raise ValueError(f'{context} must be an object.')
        if key not in record or not isinstance(record[key], str):
            raise ValueError(f'{context}.{key} must be a string.')
        return record[key]

    participants = array('participants')
    rooms = array('rooms')
    workshops = array('workshops')
    existing = array('existing_assignments')
    affected_ids = array('affected_workshop_ids')

    participant_map = {}
    for participant in participants:
        pid = string_field(participant, 'id', 'Participant')
        if pid in participant_map:
            raise ValueError(f'Duplicate participant ID: {pid!r}.')
        string_field(participant, 'first_choice', 'Participant')
        string_field(participant, 'second_choice', 'Participant')
        participant_map[pid] = participant

    remaining = {}
    for room in rooms:
        rid = string_field(room, 'id', 'Room')
        if rid in remaining:
            raise ValueError(f'Duplicate room ID: {rid!r}.')
        capacity = room.get('capacity')
        if type(capacity) is not int or capacity < 0:
            raise ValueError(f'Room {rid!r} capacity must be a nonnegative integer.')
        if type(room.get('open')) is not bool:
            raise ValueError(f'Room {rid!r} open must be a boolean.')
        remaining[rid] = capacity if room['open'] else 0

    workshop_rooms = {}
    for workshop in workshops:
        wid = string_field(workshop, 'id', 'Workshop')
        if wid in workshop_rooms:
            raise ValueError(f'Duplicate workshop ID: {wid!r}.')
        rid = string_field(workshop, 'room', 'Workshop')
        if rid not in remaining:
            raise ValueError(f'Workshop {wid!r} references unknown room {rid!r}.')
        workshop_rooms[wid] = rid

    def check_workshop(wid, context):
        if wid not in workshop_rooms:
            raise ValueError(f'{context} references unknown workshop {wid!r}.')

    for participant in participants:
        for key in ('first_choice', 'second_choice'):
            check_workshop(participant[key], f'Participant {participant["id"]!r} {key}')

    affected = set()
    for wid in affected_ids:
        if not isinstance(wid, str):
            raise ValueError('Affected workshop IDs must be strings.')
        check_workshop(wid, 'Affected workshop list')
        affected.add(wid)

    previous = {}
    for assignment in existing:
        pid = string_field(assignment, 'participant_id', 'Existing assignment')
        wid = string_field(assignment, 'workshop_id', 'Existing assignment')
        if pid in previous:
            raise ValueError(f'Duplicate existing-assignment participant ID: {pid!r}.')
        check_workshop(wid, f'Existing assignment for {pid!r}')
        previous[pid] = wid

    allocated = {}

    def reserve(pid, wid):
        rid = workshop_rooms[wid]
        if remaining[rid] <= 0:
            return False
        remaining[rid] -= 1
        allocated[pid] = wid
        return True

    # Fixed reservations take precedence over all affected and new attendees.
    for participant in participants:
        pid = participant['id']
        if pid in previous and previous[pid] not in affected:
            wid = previous[pid]
            if not reserve(pid, wid):
                raise ValueError(
                    f'Fixed assignment for participant {pid!r} in workshop {wid!r} '
                    'violates room availability or shared capacity.'
                )

    # Retain affected attendees in roster order before filling free seats.
    for participant in participants:
        pid = participant['id']
        if pid in previous and previous[pid] in affected:
            reserve(pid, previous[pid])

    for participant in participants:
        pid = participant['id']
        if pid in allocated:
            continue
        for key in ('first_choice', 'second_choice'):
            if reserve(pid, participant[key]):
                break

    return {
        'assignments': [
            {'participant_id': p['id'], 'workshop_id': allocated[p['id']]}
            for p in participants if p['id'] in allocated
        ],
        'waitlist': [p['id'] for p in participants if p['id'] not in allocated]
    }
